// Full-screen Decimator results receipt. Since audit 92a1358d0 the Decimator is
// a shared-dice craps battle, so the receipt is read straight from its public
// logs: the player's final coin and run, then every paid winner ranked by stack
// x peak with their ETH and half whale passes. From audit 12daf8060 there is no
// coin: a sampled survivor set plays (`you.survived`), and jackpot-generated
// entries a wallet received can place too (`you.generatedWins`). The result
// counts as seen only once the receipt is on screen (onReady), so a load
// failure keeps it unseen.

import { CHAIN } from '../app/chain-config.js';
import { displayEth, displayToken } from '../app/scaling.js';
import { fetchProfiles } from '../app/profiles.js';
import { loadDecimatorDrawSnapshot } from '../app/decimator-draw-data.js';
import { compactUiError } from '../app/ui-error.js';
import { sfxFanfare, sfxNoWin, warmup as warmupSfx } from '../app/jackpot-sfx.js';

let active = null;
const RECEIPT_STYLES = '/app/styles/decimator-receipt.css';

/** The receipt's own sheet, attached the first time the takeover opens. */
function ensureReceiptStyles() {
  if (document.querySelector?.('link[data-decimator-receipt]')) return;
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  link.href = RECEIPT_STYLES;
  link.setAttribute('data-decimator-receipt', '');
  document.head?.appendChild(link);
}

function drawLoadErrorMessage(error) {
  const message = String(error?.shortMessage || error?.message || '').trim();
  if (/rate limit|too many requests|\b429\b|32016/i.test(message)) {
    return 'PUBLIC CHAIN DATA IS BUSY. TRY AGAIN.';
  }
  if (/sync|indexed|unavailable/i.test(message)) {
    return 'THE DECIMATOR RESULT IS STILL SYNCING. TRY AGAIN.';
  }
  return compactUiError(error, 'Decimator results could not be loaded. Try again.').toUpperCase();
}

function trim(value) {
  const text = String(value ?? '0');
  return text.includes('.') ? text.replace(/0+$/, '').replace(/\.$/, '') : text;
}

function eth(wei) {
  try { return trim(displayEth(BigInt(wei ?? 0), 4)); } catch (_error) { return '0'; }
}

function whole(wei) {
  try {
    const value = Number(trim(displayToken(BigInt(wei ?? 0), 0)));
    return Number.isSafeInteger(value) ? value.toLocaleString('en-US') : trim(displayToken(BigInt(wei ?? 0), 0));
  } catch (_error) { return '—'; }
}

/** "0.29 ETH + 1 half pass". */
export function decimatorReceiptPrize(ethWei, halfPasses) {
  const parts = [];
  let passes = 0n;
  try { passes = BigInt(halfPasses ?? 0); } catch (_error) { passes = 0n; }
  try { if (BigInt(ethWei ?? 0) > 0n) parts.push(`${eth(ethWei)} ETH`); } catch (_error) { /* none */ }
  if (passes > 0n) parts.push(`${passes} half ${passes === 1n ? 'pass' : 'passes'}`);
  return parts.join(' + ') || '—';
}

function sumBig(rows, key) {
  return rows.reduce((total, row) => {
    try { return total + BigInt(row?.[key] ?? 0); } catch (_error) { return total; }
  }, 0n);
}

/** The viewer's line: what their coin (or survivor draw) and run did, and what it paid. */
export function decimatorReceiptVerdict(snapshot) {
  const you = snapshot?.you;
  if (!you) return { tone: 'muted', title: 'NO ENTRY', detail: 'This wallet did not burn into this Decimator.' };
  const sampled = you.survived !== undefined;
  if (you.coin === 'tails') return { tone: 'lost', title: 'TAILS', detail: 'Your final coin landed tails, so your entry sat out the dice.' };
  const peaked = you.peakMultiple == null ? null : `Your run peaked at ${you.peakMultiple}× its bankroll.`;
  const run = sampled ? peaked ?? 'Your entry survived the draw.' : peaked == null ? 'Heads.' : `Heads. ${peaked}`;
  const generatedWins = Array.isArray(you.generatedWins) ? you.generatedWins : [];
  if (you.winner || generatedWins.length) {
    const places = [...(you.winner ? [you] : []), ...generatedWins];
    const best = Math.min(...places.map((row) => Number(row.rank) || Infinity));
    const lead = you.winner
      ? run
      : generatedWins.length === 1
        ? 'A jackpot-day entry drawn for your tickets placed.'
        : `${generatedWins.length} jackpot-day entries drawn for your tickets placed.`;
    return {
      tone: 'won',
      title: best === 1 ? 'CHAMPION' : `#${best} OF ${snapshot.winnerCount ?? snapshot.winners.length}`,
      detail: `${lead} Paid ${decimatorReceiptPrize(sumBig(places, 'ethWei'), sumBig(places, 'halfPasses'))}.`,
    };
  }
  if (you.survived === false) {
    return { tone: 'lost', title: 'NOT DRAWN', detail: 'Your entry was not among the sampled survivors, so it sat out the dice.' };
  }
  if (!snapshot.ranked) {
    if (sampled && you.survived == null) {
      return { tone: 'waiting', title: 'SETTLING', detail: 'Survivors are drawn once the jackpot day fixes the field size.' };
    }
    return { tone: 'waiting', title: sampled ? 'SURVIVED' : 'HEADS', detail: `${run} The field is still settling.` };
  }
  const place = snapshot.winnerCount ? ` outside the top ${snapshot.winnerCount}` : '';
  return { tone: 'lost', title: 'NOT PLACED', detail: `${run} Your stack × peak finished${place}.` };
}

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text != null) node.textContent = String(text);
  return node;
}

function shortAddress(address) {
  const text = String(address || '');
  return text.length > 12 ? `${text.slice(0, 6)}…${text.slice(-4)}` : text;
}

function renderReceipt(snapshot, names) {
  const receipt = el('div', 'dec-receipt');
  const head = el('header', 'dec-receipt__head');
  head.appendChild(el('small', null, `LEVEL ${snapshot.level} DECIMATOR`));
  head.appendChild(el('h2', null, 'RESULTS'));
  const facts = el('dl', 'dec-receipt__facts');
  for (const [label, value] of [
    ['POOL', `${eth(snapshot.poolWei)} ETH`],
    ['ENTRANTS', Number(snapshot.generatedEntries) > 0
      ? `${Number(snapshot.entrants || 0).toLocaleString('en-US')} + ${Number(snapshot.generatedEntries).toLocaleString('en-US')} JACKPOT`
      : Number(snapshot.entrants || 0).toLocaleString('en-US')],
    ['WINNERS', snapshot.winnerCount == null ? '—' : String(snapshot.winnerCount)],
    ['FLIP BURNED', whole(snapshot.totalFlipBurned)],
  ]) {
    const item = el('div');
    item.appendChild(el('dt', null, label));
    item.appendChild(el('dd', null, value));
    facts.appendChild(item);
  }
  head.appendChild(facts);
  receipt.appendChild(head);

  const verdict = decimatorReceiptVerdict(snapshot);
  const mine = el('section', `dec-receipt__you is-${verdict.tone}`);
  mine.setAttribute('aria-label', 'Your result');
  mine.appendChild(el('strong', null, verdict.title));
  mine.appendChild(el('p', null, verdict.detail));
  if (snapshot.you?.score != null) {
    mine.appendChild(el('span', 'dec-receipt__score', `STACK ${whole(snapshot.you.stack)} · SCORE ${whole(snapshot.you.score)}`));
  }
  receipt.appendChild(mine);

  const board = el('section', 'dec-receipt__board');
  board.setAttribute('aria-label', 'Winners');
  const unpaid = snapshot.winnerCount == null ? 0 : Math.max(0, snapshot.winnerCount - snapshot.winners.length);
  board.appendChild(el('h3', null, unpaid > 0 ? `WINNERS · ${unpaid} STILL PAYING OUT` : 'WINNERS'));
  if (snapshot.winners.length === 0) {
    board.appendChild(el('p', 'dec-receipt__empty', snapshot.ranked
      ? snapshot.fieldEntries !== undefined
        ? 'No run placed. The pool returned to future prizes.'
        : 'No heads run placed. The pool returned to future prizes.'
      : 'Winners appear as the keepers settle the field.'));
  } else {
    const list = el('ol', 'dec-receipt__winners');
    for (const row of snapshot.winners) {
      const item = el('li', row.address === snapshot.you?.address ? 'is-you' : null);
      item.appendChild(el('span', 'dec-receipt__rank', row.champion ? '♛' : String(row.rank)));
      const who = names.get(row.address)?.name || shortAddress(row.address);
      item.appendChild(el('span', 'dec-receipt__name', row.address === snapshot.you?.address ? `${who} (YOU)` : who));
      item.appendChild(el('span', 'dec-receipt__peak', row.peakMultiple == null ? '—' : `${row.peakMultiple}×`));
      item.appendChild(el('span', 'dec-receipt__prize', decimatorReceiptPrize(row.ethWei, row.halfPasses)));
      list.appendChild(item);
    }
    board.appendChild(list);
  }
  receipt.appendChild(board);
  return receipt;
}

function removeActive() {
  if (!active) return;
  const { overlay, onKeydown } = active;
  active = null;
  try { document.removeEventListener('keydown', onKeydown); } catch (_error) { /* defensive */ }
  try { overlay.remove(); } catch (_error) { /* defensive */ }
  try { document.body?.classList?.remove('decimator-draw-open'); } catch (_error) { /* defensive */ }
}

export function closeDecimatorDraw() {
  removeActive();
}

export async function openDecimatorDraw({ level, player, onReady } = {}) {
  if (typeof document === 'undefined' || !document.body) return false;
  // Run before the first await so a manual click unlocks WebAudio while
  // browser user activation is still live.
  try { warmupSfx(); } catch (_error) { /* sound is optional */ }
  removeActive();
  try { ensureReceiptStyles(); } catch (_error) { /* unstyled content still reads */ }

  const overlay = document.createElement('section');
  overlay.className = 'decimator-draw-modal is-loading';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', `Level ${Number(level)} Decimator results`);
  overlay.dataset.chain = String(CHAIN.id ?? '');

  const loading = el('div', 'decimator-draw-modal__loading');
  loading.setAttribute('role', 'status');
  const loadingTitle = el('strong', null, 'LOADING DECIMATOR RESULTS');
  const loadingDetail = el('span', null, 'READING THE BATTLE FROM CHAIN…');
  loading.appendChild(loadingTitle);
  loading.appendChild(loadingDetail);
  const retry = el('button', 'decimator-draw-modal__retry', 'TRY AGAIN');
  retry.type = 'button';
  retry.hidden = true;
  loading.appendChild(retry);
  overlay.appendChild(loading);

  const close = el('button', 'decimator-draw-modal__close', 'BACK TO GAME');
  close.type = 'button';
  close.setAttribute('aria-label', 'Close Decimator results and return to the game');
  close.addEventListener('click', removeActive);
  overlay.appendChild(close);

  const onKeydown = (event) => {
    if (event?.key === 'Escape') removeActive();
  };
  active = { overlay, onKeydown };
  document.addEventListener('keydown', onKeydown);
  document.body.classList.add('decimator-draw-open');
  document.body.appendChild(overlay);

  let loadPending = null;
  let readyNotified = false;
  const mount = async () => {
    if (loadPending) return loadPending;
    loadPending = (async () => {
      overlay.classList.add('is-loading');
      overlay.classList.remove('is-error');
      loading.hidden = false;
      loadingTitle.textContent = 'LOADING DECIMATOR RESULTS';
      loadingDetail.textContent = 'READING THE BATTLE FROM CHAIN…';
      retry.hidden = true;
      retry.disabled = true;
      try {
        const snapshot = await loadDecimatorDrawSnapshot({ level, player });
        let names = new Map();
        try { names = await fetchProfiles(snapshot.winners.map((row) => row.address)); }
        catch (_error) { /* a winner without a profile keeps its address */ }
        if (!active || active.overlay !== overlay || !overlay.isConnected) return false;
        overlay.querySelector('.dec-receipt')?.remove();
        overlay.insertBefore(renderReceipt(snapshot, names), close);
        overlay.classList.remove('is-loading', 'is-error');
        loading.hidden = true;
        try { close.focus(); } catch (_error) { /* focus is best-effort */ }
        const verdict = decimatorReceiptVerdict(snapshot);
        try {
          if (verdict.tone === 'won') sfxFanfare(verdict.title === 'CHAMPION');
          else if (verdict.tone === 'lost') sfxNoWin();
        } catch (_error) { /* sound remains decorative */ }
        // The result counts as seen only once the receipt is actually on screen.
        if (!readyNotified) {
          readyNotified = true;
          try { onReady?.(); } catch (_error) { /* presentation receipt is best-effort */ }
        }
        return true;
      } catch (error) {
        if (!active || active.overlay !== overlay || !overlay.isConnected) return false;
        // Loading failures belong inside the fullscreen they opened. Removing
        // it here made an RPC rate limit look like a failed game transaction.
        overlay.classList.add('is-error');
        loadingTitle.textContent = 'RESULTS UNAVAILABLE';
        loadingDetail.textContent = drawLoadErrorMessage(error);
        retry.hidden = false;
        retry.disabled = false;
        try { retry.focus(); } catch (_focusError) { /* close remains available */ }
        return false;
      } finally {
        loadPending = null;
      }
    })();
    return loadPending;
  };
  retry.addEventListener('click', (event) => {
    try { event.stopPropagation(); } catch (_error) { /* defensive */ }
    void mount();
  });

  await mount();
  // Once the takeover is mounted, a data error is recoverable in place and is
  // not a failed Pending action. The result remains unseen until onReady fires.
  return Boolean(active?.overlay === overlay && overlay.isConnected);
}
